package br.com.marquesautodetail.api.agendamento; import br.com.marquesautodetail.api.agendamento.dto.AgendamentoResponse; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController public class EmpresaAgendamentoController{ private final AgendamentoService service; public EmpresaAgendamentoController(AgendamentoService service){this.service=service;} @GetMapping("/empresas/{empresaId}/agendamentos") public List<AgendamentoResponse> porEmpresa(@PathVariable Long empresaId){return service.porEmpresa(empresaId);} }
